package com.marketplace;
import java.util.*;import java.time.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.stereotype.*;import org.springframework.security.crypto.password.*;import org.springframework.security.web.csrf.CsrfToken;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.mail.*;import org.springframework.mail.javamail.JavaMailSender;
@Component class Access {final Db db;Access(Db d){db=d;}Map<String,Object> user(HttpSession s){Object id=s.getAttribute("uid");if(id==null)throw new Failure(401,"LOGIN_REQUIRED","Please sign in");var u=db.one("select id,email,name,role,active,auth_version from users where id=?",id);if(!Boolean.TRUE.equals(u.get("active")))throw new Failure(403,"SUSPENDED","Account suspended");if(!Objects.equals(s.getAttribute("auth_version"),u.get("auth_version")))throw new Failure(401,"SESSION_EXPIRED","Please sign in again");u.remove("auth_version");return u;}long uid(HttpSession s){return Db.n(user(s),"id");}long role(HttpSession s,String role){var u=user(s);if(!role.equals(u.get("role")))throw new Failure(403,"FORBIDDEN","This role is not permitted");return Db.n(u,"id");}long store(HttpSession s){return db.id("select id from stores where user_id=? and active=true",role(s,"SELLER"));}}
@RestController @RequestMapping("/api/auth") public class Identity {
final Db d;final Access a;final PasswordEncoder enc;final StringRedisTemplate redis;final JavaMailSender mail;Identity(Db d,Access a,PasswordEncoder e,StringRedisTemplate r,JavaMailSender m){this.d=d;this.a=a;enc=e;redis=r;mail=m;}
record Credentials(@Email @NotBlank String email,@NotBlank @Size(min=10,max=100) String password,String name){}
@GetMapping("/csrf") Object csrf(CsrfToken t){return Map.of("token",t.getToken());}
@GetMapping("/me") Object me(HttpSession s){return a.user(s);}
@PostMapping("/login") Object login(@Valid @RequestBody Credentials c,HttpServletRequest req){String key="login:"+req.getRemoteAddr()+":"+c.email().toLowerCase(Locale.ROOT);Long count=redis.opsForValue().increment(key);if(count!=null&&count==1)redis.expire(key,Duration.ofMinutes(1));if(count!=null&&count>20)throw new Failure(429,"RATE_LIMIT","Please wait a minute");var us=d.all("select * from users where lower(email)=?",c.email().toLowerCase(Locale.ROOT));if(us.isEmpty()||!enc.matches(c.password(),Db.str(us.get(0),"password")))throw new Failure(401,"BAD_CREDENTIALS","Invalid email or password");req.getSession().invalidate();req.getSession(true).setAttribute("uid",us.get(0).get("id"));req.getSession().setAttribute("auth_version",us.get(0).get("auth_version"));return a.user(req.getSession());}
@PostMapping("/register") @Transactional Object register(@Valid @RequestBody Credentials c){if(c.name()==null||c.name().isBlank()||c.name().length()>100)throw new IllegalArgumentException();long id=d.id("insert into users(email,password,name,role) values(?,?,?,'CUSTOMER') returning id",c.email().toLowerCase(Locale.ROOT),enc.encode(c.password()),c.name());return Map.of("id",id);}
@PostMapping("/logout") Object logout(HttpSession s){s.invalidate();return Map.of("ok",true);}
@PostMapping("/forgot") @Transactional Object forgot(@RequestBody Map<String,String> b){var users=d.all("select id,email from users where email=?",b.getOrDefault("email","").toLowerCase(Locale.ROOT));if(!users.isEmpty()){var u=users.get(0);String token=UUID.randomUUID().toString();d.exec("insert into password_resets values(?,?,now()+interval '20 minutes')",token,u.get("id"));SimpleMailMessage m=new SimpleMailMessage();m.setFrom("support@marketplace.local");m.setTo(Db.str(u,"email"));m.setSubject("MARKETPLACE password reset");m.setText("Open http://localhost:8088/reset?token="+token);mail.send(m);}return Map.of("message","If the account exists, a reset email was sent.");}
@PostMapping("/reset") @Transactional Object reset(@RequestBody Map<String,String>b){String p=b.getOrDefault("password","");if(p.length()<10||p.length()>100)throw new IllegalArgumentException();var r=d.one("delete from password_resets where token=? and expires>now() returning user_id",b.get("token"));d.exec("update users set password=?,auth_version=auth_version+1 where id=?",enc.encode(p),r.get("user_id"));return Map.of("message","Password changed. Sign in again.");}
}
